/* =================== COMPANY WEB APP =================== */
const NAV=[["overview","Overview","grid"],["board","Projects","brief"],["talent","Find talent","users"],["messages","Messages","chat"],["payments","Payments","card"]];
const FEE=.12,IVA=.19;
const coEscrow=()=>Object.entries(S.work).filter(([k])=>P(k).co==="andina").reduce((a,[k,w])=>a+w.ms.filter(m=>m.st!=="paid").reduce((x,m)=>x+m.a,0),0);
const inReview=()=>Object.entries(S.work).filter(([k,w])=>P(k).co==="andina").flatMap(([k,w])=>w.ms.map((m,i)=>[k,i,m]).filter(x=>x[2].st==="review"));
function coGo(v,p){S.coRoute=[v,p];coClose();coRender();const c=$("#wcont");if(c)c.scrollTop=0;}
function coRender(){
  const [v,p]=S.coRoute;
  $("#url").textContent="app.skillbridge.co/company/"+(v==="proj"?"projects/"+p:v);
  const unr=Object.entries(S.threads).filter(([k,t])=>t.co==="andina"&&t.msgs.at(-1)[0]==="stu").length;
  const navCnt={messages:unr,overview:inReview().length};
  $("#side").innerHTML=`<div class="row" style="padding:4px 8px 16px;gap:10px">${BRANDMARK(26)}<b class="lbl-t" style="font-size:1.05rem;letter-spacing:-.02em">SkillBridge</b><span class="pill p-brand lbl-t">Business</span></div>
   <div class="wsw">${logo("andina",34)}<div class="wtx grow"><b class="s ell" style="display:block">Exportadora Andina</b><span class="xs muted ell" style="display:block">Laura Méndez · Admin</span></div></div>
   ${NAV.map(([k,l,i])=>`<button class="nv" aria-current="${(v===k||(v==="proj"&&k==="board"))?"page":"false"}" onclick="coGo('${k}')" title="${l}">${ic(i,19)}<span class="lbl-t">${l}</span>${navCnt[k]?`<span class="cnt">${navCnt[k]}</span>`:""}</button>`).join("")}
   <div class="sp"></div><div class="upsell"><b>Need help hiring?</b><br>Our team can pre-select 3 students for you in 24 h.</div>
   <button class="nv" onclick="wtoast('Settings are not part of this prototype','info')">${ic("gear",19)}<span class="lbl-t">Settings</span></button>`;
  $("#mtabs").innerHTML=NAV.map(([k,l])=>`<button aria-current="${v===k||(v==="proj"&&k==="board")?"page":"false"}" onclick="coGo('${k}')">${l}</button>`).join("");
  $("#wtop").innerHTML=`<div class="search">${ic("search",17)}<input placeholder="Search projects, students, invoices" aria-label="Search" onkeydown="if(event.key==='Enter'){S.tf.q=this.value;coGo('talent')}"></div><span class="grow"></span>
   <button class="btn sm" onclick="openPost()">${ic("plus",16,2.4)} New project</button>
   <button class="ib flat" aria-label="Notifications" onclick="coGo('overview')">${ic("bell",20)}${inReview().length?`<span class="bd" style="border-color:var(--card)">${inReview().length}</span>`:""}</button>${avP("Laura Méndez","#14532D","#2F8A57",36)}`;
  $("#wcont").innerHTML=`<div class="in-f page" style="position:static;overflow:visible">${CV[v](p)}</div>`;
  const a=CVA[v];if(a)a(p);
  renderTray();renderGuide();
}
const CV={},CVA={};
function wtoast(m,i="check"){const t=$("#wtoast");t.innerHTML=ic(i,17,2.4)+esc(m);t.classList.add("on");clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove("on"),2600);}
function coModal(h,w){const mw=$("#mwrap");mw.innerHTML=`<div class="modal" style="${w?`width:min(${w}px,100%)`:""}" role="dialog" aria-modal="true">${h}</div>`;mw.classList.add("on");}
function coDrawer(h){$("#drawer").innerHTML=h;$("#drawer").classList.add("on");}
function coClose(){const m=$("#mwrap"),d=$("#drawer");if(m)m.classList.remove("on");if(d)d.classList.remove("on");}
const mh=t=>`<div class="mh"><h3>${t}</h3><button class="ib flat" aria-label="Close" onclick="coClose()">${ic("close",20)}</button></div>`;
const statusPill=p=>{const w=S.work[p.id];if(p.status==="draft")return'<span class="pill p-gray">Draft</span>';if(p.status==="open")return`<span class="pill p-brand">Open · ${(S.coApps[p.id]||[]).length} applicants</span>`;if(p.status==="done")return'<span class="pill p-ok">Completed</span>';if(w&&w.ms.some(m=>m.st==="review"))return'<span class="pill p-warn">To review</span>';return'<span class="pill p-coral">In progress</span>';};

/* ---------- overview ---------- */
CV.overview=()=>{const act=coProjects().filter(p=>p.status==="active");const rev=inReview();const spent=S.coSpend.reduce((a,b)=>a+b,0);
 const att=[...rev.map(([k,i,m])=>{const s=ST(S.work[k].stu);return `<div class="att">${av(s,36)}<div class="grow"><b class="s">${esc(s.n.split(" ")[0])} submitted "${esc(m.t)}"</b><div class="xs muted">${esc(P(k).title)} · ${fmt(m.a)} waiting for your approval</div></div><button class="btn sm" onclick="S.ptab2='work';coGo('proj','${k}')">Review</button></div>`;}),
  ...coProjects().filter(p=>p.status==="open").map(p=>`<div class="att"><span class="ico" style="background:var(--brand-soft);color:var(--brand-ink)">${ic("users",18)}</span><div class="grow"><b class="s">${(S.coApps[p.id]||[]).length} students applied to "${esc(p.title)}"</b><div class="xs muted">Best match: ${(S.coApps[p.id]||[]).length?ST(S.coApps[p.id][0][0]).n+" · "+S.coApps[p.id][0][1]+"%":"waiting for applications"}</div></div><button class="btn sm sec" onclick="S.ptab2='apps';coGo('proj','${p.id}')">See applicants</button></div>`),
  ...coProjects().filter(p=>p.status==="draft").map(p=>`<div class="att"><span class="ico" style="background:var(--chip);color:var(--muted)">${ic("pen",18)}</span><div class="grow"><b class="s">Finish your draft "${esc(p.title)}"</b><div class="xs muted">Budget ${fmt(p.pay)} · not published</div></div><button class="btn sm sec" onclick="openPost('${p.id}')">Continue</button></div>`)].join("");
 return `<div class="wh"><div><h1>Good morning, Laura</h1><p>Here is what's happening at Exportadora Andina today.</p></div><div class="row"><button class="btn sec sm" onclick="coGo('talent')">${ic("search",16)} Find talent</button><button class="btn sm" onclick="openPost()">${ic("plus",16,2.4)} New project</button></div></div>
  <div class="kpis">
   <div class="kpi"><small>${ic("brief",15)}Active projects</small><b>${act.length}</b><span class="dl muted">${coProjects().filter(p=>p.status==="open").length} open for applications</span></div>
   <div class="kpi"><small>${ic("lock",15)}Held in escrow</small><b class="num">${kfmt(coEscrow())}</b><span class="dl muted">Released when you approve</span></div>
   <div class="kpi"><small>${ic("users",15)}Applicants this week</small><b>${Object.values(S.coApps).reduce((a,l)=>a+l.length,0)}</b><span class="dl" style="color:var(--ok)">▲ 4 vs last week</span></div>
   <div class="kpi"><small>${ic("clock",15)}Average time to hire</small><b>2.1 days</b><span class="dl muted">Platform average: 3.4 days</span></div></div>
  <div class="g2"><div class="col" style="gap:14px">
   <section class="wcard"><div class="hd"><h3>Needs your attention</h3><span class="pill ${att?"p-coral":"p-ok"}">${att?(rev.length+coProjects().filter(p=>p.status==="open"||p.status==="draft").length)+" items":"All clear"}</span></div><div class="bdy">${att||'<p class="s muted">Nothing to do right now.</p>'}</div></section>
   <section class="wcard"><div class="hd"><h3>Active projects</h3><button class="link" onclick="coGo('board')">View board</button></div><div class="bdy scrollx"><table class="tbl"><thead><tr><th>Project</th><th>Student</th><th>Progress</th><th>Next milestone</th><th class="r">In escrow</th></tr></thead><tbody>
    ${act.map(p=>{const w=S.work[p.id],s=ST(w.stu),nx=w.ms.find(m=>m.st!=="paid");return `<tr class="clk" onclick="S.ptab2='work';coGo('proj','${p.id}')"><td><b class="s">${esc(p.title)}</b><div class="xs muted">${p.area}</div></td><td><span class="row" style="gap:8px">${av(s,28)}<span class="s ell">${esc(s.n)}</span></span></td>
     <td style="min-width:120px"><div class="row" style="gap:8px"><div class="bar grow"><i style="width:${progress(w)}%"></i></div><span class="xs b">${progress(w)}%</span></div></td><td class="s">${nx?`${esc(nx.t)}${nx.st==="review"?' <span class="pill p-warn">To review</span>':""}`:"Done"}</td><td class="r num b">${fmt(w.ms.filter(m=>m.st!=="paid").reduce((a,m)=>a+m.a,0))}</td></tr>`;}).join("")}</tbody></table></div></section></div>
   <div class="col" style="gap:14px">
   <section class="wcard"><div class="hd"><h3>Spending on students</h3><span class="xs muted">2026 · ${kfmt(spent)}</span></div><div class="bdy"><div class="fig" id="cchart" style="height:170px"></div>
    <div class="card mt10" style="background:var(--ok-soft);border-color:transparent;box-shadow:none"><div class="s" style="color:var(--ok)"><b>${coProjects().filter(p=>p.status!=="draft").length} projects done without a new hire.</b> A temporary assistant for the same months would mean a salary plus social charges every month, even when there is no work.</div></div></div></section>
   <section class="wcard"><div class="hd"><h3>Upcoming deadlines</h3></div><div class="bdy">${Object.entries(S.work).filter(([k])=>P(k).co==="andina"&&P(k).status==="active").flatMap(([k,w])=>w.ms.filter(m=>m.st!=="paid").slice(0,1).map(m=>[k,m,w])).map(([k,m,w])=>`<div class="att"><span class="ico" style="background:var(--chip);color:var(--ink2);flex-direction:column;font-size:.62rem;font-weight:700;line-height:1.1"><span>${m.due.split(" ")[0].toUpperCase()}</span><span style="font-size:.9rem">${m.due.split(" ")[1]}</span></span><div class="grow"><b class="s">${esc(m.t)}</b><div class="xs muted">${esc(ST(w.stu).n)} · ${esc(P(k).title)}</div></div></div>`).join("")}</div></section></div></div>`;};
CVA.overview=()=>barChart($("#cchart"),MONTHS.map((m,i)=>({l:m,v:S.coSpend[i],hi:i===5})),{h:170,c:"var(--brand)",label:"Spending per month"});

/* ---------- board ---------- */
CV.board=()=>{const cols=[["Draft",p=>p.status==="draft"],["Open",p=>p.status==="open"],["In progress",p=>p.status==="active"&&!S.work[p.id].ms.some(m=>m.st==="review")],["To review",p=>p.status==="active"&&S.work[p.id].ms.some(m=>m.st==="review")],["Completed",p=>p.status==="done"]];
 return `<div class="wh"><div><h1>Projects</h1><p>${coProjects().length} projects · drag-free board, click a card to open it</p></div><button class="btn sm" onclick="openPost()">${ic("plus",16,2.4)} New project</button></div>
  <div class="kanban">${cols.map(([t,f])=>{const l=coProjects().filter(f);return `<div class="kcol"><div class="kh">${t}<span class="n">${l.length}</span></div>${l.map(p=>{const w=S.work[p.id];const s=w?ST(w.stu):null;return `<div class="kc" onclick="${p.status==="draft"?`openPost('${p.id}')`:`S.ptab2='${p.status==="open"?"apps":"work"}';coGo('proj','${p.id}')`}">${cat(p.area,1)}<div class="ti">${esc(p.title)}</div>
   ${w?`<div class="bar"><i style="width:${p.status==="done"?100:progress(w)}%"></i></div>`:""}<div class="between mt10"><span class="row" style="gap:6px">${s?av(s,24)+`<span class="xs ell">${esc(s.n.split(" ")[0])}</span>`:p.status==="open"?`<span class="xs muted">${(S.coApps[p.id]||[]).length} applicants</span>`:'<span class="xs muted">Not published</span>'}</span><b class="xs num">${kfmt(p.pay)}</b></div></div>`;}).join("")||'<p class="xs muted" style="padding:4px">Nothing here</p>'}</div>`;}).join("")}</div>`;};

/* ---------- project detail ---------- */
CV.proj=pid=>{const p=P(pid),w=S.work[pid],open=p.status==="open";let tab=S.ptab2||(open?"apps":"work");if(open&&tab==="work")tab="apps";if(!open&&tab==="apps")tab="work";
 const tabs=open?[["apps",`Applicants (${(S.coApps[pid]||[]).length})`],["brief","Brief"]]:[["work","Work and payments"],["brief","Brief"]];
 let body="";
 if(tab==="apps"){const l=(S.coApps[pid]||[]).slice().sort({match:(a,b)=>b[1]-a[1],price:(a,b)=>a[3]-b[3],rating:(a,b)=>ST(b[0]).rate-ST(a[0]).rate}[S.appSort]);
  body=l.length?`<div class="between" style="margin-bottom:10px"><span class="s muted">Ranked by our matching score. Click a row to read the proposal.</span><div class="segc" style="width:320px">${[["match","Best match"],["price","Lowest price"],["rating","Rating"]].map(([k,t])=>`<button aria-pressed="${S.appSort===k}" onclick="S.appSort='${k}';coRender()">${t}</button>`).join("")}</div></div>
   <div class="wcard scrollx"><table class="tbl"><thead><tr><th>Student</th><th>Match</th><th>Rating</th><th>Languages</th><th class="r">Asks</th><th>Applied</th><th></th></tr></thead><tbody>
   ${l.map(([sid,m,msg,pr,d])=>{const s=ST(sid);return `<tr class="clk" onclick="appDrawer('${pid}','${sid}')"><td><span class="row">${av(s,34)}<span><b class="s">${esc(s.n)}</b><div class="xs muted">${s.prog} · ${s.uni}</div></span></span></td>
    <td style="min-width:120px"><div class="row" style="gap:8px"><div class="bar grow"><i style="width:${m}%;background:${m>=85?"var(--brand)":m>=60?"var(--faint)":"var(--line)"}"></i></div><b class="xs">${m}%</b></div></td>
    <td class="s">${s.rate?`<span class="stars">★</span> ${s.rate.toFixed(1)} <span class="xs muted">(${s.done})</span>`:'<span class="pill p-warn">New</span>'}</td><td><span class="row" style="gap:4px">${s.langs.map(langS).join("")}</span></td>
    <td class="r num b">${fmt(pr)}${pr<p.pay?`<div class="xs" style="color:var(--ok);font-weight:600">−${kfmt(p.pay-pr)}</div>`:""}</td><td class="xs muted">${d}</td><td><button class="btn sm sec" onclick="event.stopPropagation();appDrawer('${pid}','${sid}')">View</button></td></tr>`;}).join("")}</tbody></table></div>`:
   `<div class="wcard" style="padding:28px;text-align:center"><div style="color:var(--brand)">${ic("send",34)}</div><h3 style="margin:8px 0 4px">Your project is live</h3><p class="s muted" style="margin:0 0 16px">We notified the ${matchCount(p)} students who match. First applications usually arrive within 6 hours.</p>
    <div class="tgrid" style="text-align:left">${topMatches(p).map(s=>talentCard(s)).join("")}</div></div>`;}
 if(tab==="work"){const s=ST(w.stu);body=`<div class="g2" style="margin-top:0"><section class="wcard"><div class="hd"><h3>Milestones</h3><span class="xs muted">${fmt(w.ms.filter(m=>m.st==="paid").reduce((a,m)=>a+m.a,0))} released of ${fmt(w.ms.reduce((a,m)=>a+m.a,0))}</span></div><div class="bdy">
   ${w.ms.map((m,i)=>`<div class="msrow"><span class="ix ${m.st}">${m.st==="paid"?ic("check",15,3):i+1}</span><div class="grow"><div class="between"><b class="s">${esc(m.t)}</b><b class="s num">${fmt(m.a)}</b></div>
    <div class="row mt6" style="gap:8px">${{paid:'<span class="pill p-ok">Paid</span>',review:'<span class="pill p-warn">Submitted, waiting for you</span>',active:'<span class="pill p-brand">In progress</span>',todo:'<span class="pill p-gray">Not started</span>'}[m.st]}<span class="xs muted">Due ${m.due}</span></div>
    ${m.st==="review"?`<div class="row mt10"><button class="btn sm" onclick="approveModal('${pid}',${i})">${ic("check",15,2.6)} Approve and release ${kfmt(m.a)}</button><button class="btn sm sec" onclick="changesModal('${pid}',${i})">Ask for changes</button></div>`:""}</div></div>`).join("")}</div></section>
   <div class="col" style="gap:14px"><section class="wcard"><div class="hd"><h3>Student</h3></div><div class="bdy"><div class="row">${av(s,46)}<div class="grow"><b>${esc(s.n)}</b><div class="xs muted">${s.prog} · ${s.uni}</div><div class="xs"><span class="stars">★</span> ${s.rate||"New"} · answers in ${s.resp}</div></div></div>
    <div class="row mt14"><button class="btn sm sec grow" onclick="S.coThread='andina-${s.id}';if(!S.threads['andina-${s.id}'])S.threads['andina-${s.id}']={co:'andina',stu:'${s.id}',ctx:'${esc(p.title).slice(0,24)}',who:'Laura Méndez',msgs:[]};coGo('messages')">${ic("chat",16)} Message</button><button class="btn sm sec grow" onclick="stuDrawer('${s.id}')">Profile</button></div></div></section>
   <section class="wcard"><div class="hd"><h3>Files</h3><span class="xs muted">${w.files.length}</span></div><div class="bdy">${w.files.map(f=>fileRow(f,1)).join("")||'<p class="s muted">No files yet</p>'}</div></section>
   <section class="wcard"><div class="hd"><h3>Escrow</h3></div><div class="bdy"><div class="lines"><div><span class="muted">Funded</span><b class="num">${fmt(w.ms.reduce((a,m)=>a+m.a,0))}</b></div><div><span class="muted">Released</span><b class="num">${fmt(w.ms.filter(m=>m.st==="paid").reduce((a,m)=>a+m.a,0))}</b></div><div class="tot"><span>Still held</span><span class="num">${fmt(w.ms.filter(m=>m.st!=="paid").reduce((a,m)=>a+m.a,0))}</span></div></div></div></section></div></div>`;}
 if(tab==="brief")body=`<div class="g2" style="margin-top:0"><section class="wcard"><div class="hd"><h3>Brief</h3></div><div class="bdy"><p style="margin:0 0 14px;line-height:1.6">${esc(p.desc)}</p><div class="lbl">Deliverables</div>${p.deliv.map((d,i)=>`<div class="ms"><span class="ix">${i+1}</span><span class="s grow">${esc(d)}</span></div>`).join("")}</div></section>
  <section class="wcard"><div class="hd"><h3>Details</h3></div><div class="bdy"><div class="lines"><div><span class="muted">Budget</span><b class="num">${fmt(p.pay)}</b></div><div><span class="muted">Duration</span><b>${p.dur}</b></div><div><span class="muted">Effort</span><b>About ${p.hours} h</b></div><div><span class="muted">Mode</span><b>${p.mode}</b></div></div><div class="lbl mt14">Skills</div><div class="row" style="flex-wrap:wrap;gap:6px">${p.skills.map(s=>`<span class="chip">${s}</span>`).join("")}${p.langs.map(lang).join("")}</div></div></section></div>`;
 return `<button class="link row" style="gap:4px;margin-bottom:10px" onclick="coGo('board')">${ic("back",15,2.4)} Projects</button>
  <div class="wh"><div><div class="row" style="gap:8px;margin-bottom:8px">${cat(p.area)}${statusPill(p)}</div><h1>${esc(p.title)}</h1><p>${fmt(p.pay)} · ${p.dur} · ${p.mode}${p.posted?" · posted "+p.posted:""}</p></div>
   ${open?`<button class="btn sm sec" onclick="wtoast('Link copied: skillbridge.co/p/${pid}','copy')">${ic("share",16)} Share</button>`:""}</div>
  <div class="tabs" role="tablist">${tabs.map(([k,t])=>`<button role="tab" aria-selected="${tab===k}" onclick="S.ptab2='${k}';coRender()">${t}</button>`).join("")}</div>${body}`;};
const matchCount=p=>STUDENTS.filter(s=>p.langs.every(l=>s.langs.includes(l))||s.areas.includes(p.area)).length*4+3;
const topMatches=p=>STUDENTS.filter(s=>s.areas.includes(p.area)||p.langs.every(l=>s.langs.includes(l))).sort((a,b)=>b.rate-a.rate).slice(0,3);
function appDrawer(pid,sid){const a=S.coApps[pid].find(x=>x[0]===sid),s=ST(sid),p=P(pid),sl=S.shortlist.has(sid);
 coDrawer(`<div class="dh"><b>Application</b><button class="ib flat" aria-label="Close" onclick="coClose()">${ic("close",20)}</button></div><div class="db">
  <div class="row">${av(s,56)}<div class="grow"><b style="font-size:1.1rem">${esc(s.n)}</b><div class="s muted">${s.prog} · ${s.sem}</div><div class="xs muted">${s.uni} · ${s.town}</div></div></div>
  <div class="stats3 mt14"><div><b>${a[1]}%</b><small>Match</small></div><div><b>${s.rate?s.rate.toFixed(1):"New"}</b><small>Rating</small></div><div><b>${s.done}</b><small>Projects</small></div></div>
  <div class="lbl mt20">Proposal</div><div class="card" style="box-shadow:none"><p class="s" style="margin:0;line-height:1.55">"${esc(a[2])}"</p></div>
  <div class="lines mt14"><div><span class="muted">Asks</span><b class="num">${fmt(a[3])}</b></div><div><span class="muted">Your budget</span><b class="num">${fmt(p.pay)}</b></div><div><span class="muted">Availability</span><b>${s.avail}</b></div><div><span class="muted">Answers in</span><b>${s.resp}</b></div></div>
  <div class="lbl mt14">Languages and skills</div><div class="row" style="flex-wrap:wrap;gap:6px">${s.langs.map(lang).join("")}${s.skills.map(k=>`<span class="chip">${k}</span>`).join("")}</div>
  ${sid==="s1"?`<div class="lbl mt14">Certificates on SkillBridge</div>${S.certs.map(c=>`<div class="between s" style="padding:5px 0"><span>${esc(c.title)}</span><span class="pill p-ok">${c.rate.toFixed(1)} ★</span></div>`).join("")}`:""}
  <div class="row mt14" style="gap:6px"><span class="pill p-ok">${ic("check",11,3)}University email</span><span class="pill p-ok">${ic("check",11,3)}ID verified</span></div></div>
  <div class="df"><button class="btn sec sm" onclick="toggleSL('${sid}');appDrawer('${pid}','${sid}')">${sl?"★ Shortlisted":"☆ Shortlist"}</button><button class="btn sm grow" onclick="checkout('${pid}','${sid}')">Hire ${esc(s.n.split(" ")[0])}</button></div>`);}
function checkout(pid,sid,pm){const a=S.coApps[pid].find(x=>x[0]===sid),s=ST(sid),p=P(pid),pay=a[3],fee=pay*FEE,iva=fee*IVA;S.pm=pm||S.pm||"PSE";$("#drawer").classList.remove("on");
 const ms=msSplit(Object.assign({},p,{pay}));
 coModal(`${mh("Hire and fund the escrow")}<div class="mb"><div class="wiz2"><div>
  <div class="row">${av(s,44)}<div><b>${esc(s.n)}</b><div class="xs muted">${esc(p.title)}</div></div></div>
  <div class="lbl mt20">Milestones</div>${ms.map((m,i)=>`<div class="ms"><span class="ix">${i+1}</span><span class="s grow">${esc(m.t)}</span><b class="s num">${fmt(m.a)}</b></div>`).join("")}
  <div class="lbl mt20">Pay with</div>${[["PSE","Bank transfer · Bancolombia empresas","#123F7C"],["Nequi","Nequi Negocios","#4B1E78"],["Card","Visa corporate •••• 4410","#1A1F71"]].map(([n,d,c])=>`<div class="radio ${S.pm===n?"on":""}" onclick="checkout('${pid}','${sid}','${n}')"><span class="rd"></span><span class="pm" style="background:${c}">${n.toUpperCase().slice(0,4)}</span><div><b class="s">${n}</b><div class="xs muted">${d}</div></div></div>`).join("")}</div>
  <div class="preview"><b>Summary</b><div class="lines mt10"><div><span>Payment to ${esc(s.n.split(" ")[0])}</span><span class="num">${fmt(pay)}</span></div><div><span class="muted">SkillBridge fee (12%)</span><span class="num muted">${fmt(fee)}</span></div><div><span class="muted">IVA 19% on the fee</span><span class="num muted">${fmt(iva)}</span></div><div class="tot"><span>Total today</span><span class="num">${fmt(pay+fee+iva)}</span></div></div>
   <div class="card mt14" style="box-shadow:none"><div class="row" style="align-items:flex-start"><span style="color:var(--ok)">${ic("lock",20)}</span><p class="xs" style="margin:0;line-height:1.5">The money stays with SkillBridge. ${esc(s.n.split(" ")[0])} only gets each part when you approve it. If the project fails, you get it back.</p></div></div>
   <div class="subt mt10" id="agree" onclick="this.classList.toggle('on');this.querySelector('.cb').classList.toggle('on');$('#payb').disabled=!this.classList.contains('on')"><span class="cb">${ic("check",13,3)}</span><span class="xs" style="text-decoration:none!important;color:var(--ink)!important">I accept the standard contract (scope, IP, Ley 1581)</span></div></div></div></div>
  <div class="mf"><button class="btn sec" onclick="coClose()">Cancel</button><button class="btn" id="payb" disabled onclick="hire('${pid}','${sid}',${pay})">${ic("lock",16)} Pay ${fmt(pay+fee+iva)} and hire</button></div>`,900);}
function hire(pid,sid,pay){const p=P(pid),s=ST(sid),ms=msSplit(Object.assign({},p,{pay}));
 p.status="active";p.stu=sid;p.pay=pay;
 S.work[pid]={stu:sid,ms:ms.map((m,i)=>({t:m.t,a:m.a,st:i===0?"active":"todo",due:["Nov 28","Dec 2","Dec 5"][i],sub:[["Start: "+m.t.toLowerCase(),0],["Send draft",0]]})),files:[],act:[["Contract signed by both parties","Today"],[`Exportadora Andina funded ${fmt(pay)} into escrow`,"Today"]]};
 S.coSpend[5]+=0;S.invoices.unshift({n:"SB-INV-10"+(50+S.invoices.length),p:pid,d:"Nov 23",a:pay,st:"Escrow"});
 if(S.apps[pid]){if(sid==="s1"){S.apps[pid].st="hired";S.apps[pid].price=pay;}else S.apps[pid].st="declined";}
 if(sid==="s1"){S.notifs.unshift({t:`You're hired! Exportadora Andina funded ${fmt(pay)} for "${p.title}"`,w:"now",go:["workspace",pid],u:1});banner("You're hired by Exportadora Andina",`${fmt(pay)} is already in escrow for you`,["workspace",pid]);}
 coModal(`<div class="mb"><div class="done" style="padding:20px"><div class="tick">${ic("check",44,3)}</div><h2>${esc(s.n.split(" ")[0])} is hired</h2><p class="muted" style="margin:0">${fmt(pay)} is safe in escrow. ${esc(s.n.split(" ")[0])} got a notification and can start today.</p></div></div>
  <div class="mf"><button class="btn sec" onclick="coClose()">Close</button><button class="btn" onclick="S.ptab2='work';coGo('proj','${pid}')">Open the project</button></div>`,520);
 S.ptab2="work";coRender();confettiWeb();}
function confettiWeb(){confetti($("#web"));}
function approveModal(pid,i){const w=S.work[pid],m=w.ms[i],s=ST(w.stu);coModal(`${mh("Approve this milestone?")}<div class="mb"><p style="margin:0 0 14px">You are about to release <b>${fmt(m.a)}</b> to ${esc(s.n)} for "${esc(m.t)}".</p>
 <div class="card" style="box-shadow:none"><div class="lbl">Files delivered</div>${w.files.slice(0,3).map(f=>fileRow(f,1)).join("")||'<p class="s muted">No files</p>'}</div><p class="xs muted mt10">After approval the payment can't be taken back. If something is missing, ask for changes instead.</p></div>
 <div class="mf"><button class="btn sec" onclick="coClose()">Not yet</button><button class="btn" onclick="approve('${pid}',${i})">${ic("check",16,2.6)} Approve and release</button></div>`,560);}
function approve(pid,i){const w=S.work[pid],m=w.ms[i],s=ST(w.stu),p=P(pid);m.st="paid";(m.sub||[]).forEach(x=>x[1]=1);w.act.push([`Laura approved "${m.t}". ${fmt(m.a)} released`,"Today"]);
 const nx=w.ms.find(x=>x.st==="todo");if(nx&&!w.ms.some(x=>x.st==="active"||x.st==="review"))nx.st="active";
 S.coSpend[5]+=m.a;S.invoices.unshift({n:"SB-INV-10"+(50+S.invoices.length),p:pid,d:"Nov 23",a:m.a,st:"Paid"});
 if(w.stu==="s1"){S.tx.unshift({t:"Milestone paid",w:CO[p.co].n,a:m.a,d:"Today",m:"Nov"});S.notifs.unshift({t:`${CO[p.co].n} approved "${m.t}". ${fmt(m.a)} is in your wallet`,w:"now",go:["wallet"],u:1});banner(`${fmt(m.a)} just arrived`,`${CO[p.co].n} approved "${m.t}"`,["wallet"]);}
 const all=w.ms.every(x=>x.st==="paid");
 if(all){p.status="done";if(w.stu==="s1"){S.certs.unshift({id:"d0",title:p.title,co:p.co,pay:w.ms.reduce((a,x)=>a+x.a,0),rate:5,hours:p.hours,skills:p.skills.slice(0,2),code:"SB-26-5190",date:"Nov 23, 2026",area:p.area});}rateModal(pid);}
 else{coClose();wtoast(`${fmt(m.a)} released to ${s.n.split(" ")[0]}`);}
 coRender();}
function changesModal(pid,i){const w=S.work[pid],m=w.ms[i],s=ST(w.stu);coModal(`${mh("Ask for changes")}<div class="mb"><div class="field"><label for="chg">What should ${esc(s.n.split(" ")[0])} change?</label><textarea id="chg" class="inp" rows="4">Could you add a short section about prices for European buyers?</textarea></div><p class="xs muted">The milestone goes back to "in progress". The money stays in escrow.</p></div>
 <div class="mf"><button class="btn sec" onclick="coClose()">Cancel</button><button class="btn" onclick="S.work['${pid}'].ms[${i}].st='active';S.work['${pid}'].act.push(['Laura asked for changes on &quot;${esc(m.t)}&quot;','Today']);${w.stu==="s1"?`S.notifs.unshift({t:'Laura asked for changes on your milestone',w:'now',go:['workspace','${pid}'],u:1});banner('Changes requested','Exportadora Andina left a comment on your milestone',['workspace','${pid}']);`:""}coClose();coRender();wtoast('Request sent')">Send request</button></div>`,560);}
function rateModal(pid){const w=S.work[pid],s=ST(w.stu);S.rate=S.rate||5;S.rtags=S.rtags||new Set(["On time","Would hire again"]);
 coModal(`${mh("Project completed")}<div class="mb" style="text-align:center"><div class="pill p-ok">${fmt(w.ms.reduce((a,m)=>a+m.a,0))} fully paid</div><p style="margin:14px 0 8px">How was working with ${esc(s.n.split(" ")[0])}?</p>
  <div class="rstars">${[1,2,3,4,5].map(n=>`<button class="${n<=S.rate?"on":""}" aria-label="${n} stars" onclick="S.rate=${n};rateModal('${pid}')">★</button>`).join("")}</div><div class="xs muted">${["","Bad","Could be better","Okay","Good","Excellent"][S.rate]}</div>
  <div class="opts mt14" style="justify-content:center">${["On time","Great communication","High quality","Would hire again","Creative"].map(t=>`<button class="opt ${S.rtags.has(t)?"on":""}" onclick="S.rtags.has('${t}')?S.rtags.delete('${t}'):S.rtags.add('${t}');rateModal('${pid}')">${t}</button>`).join("")}</div>
  <textarea class="inp mt14" rows="3" aria-label="Public review">Our team can now greet buyers and present our coffee in French. Practical, well organised and fun.</textarea></div>
  <div class="mf"><button class="btn sec" onclick="coClose()">Skip</button><button class="btn" onclick="coClose();wtoast('Review published. Certificate sent to ${esc(s.n.split(" ")[0])}');confettiWeb()">Publish review</button></div>`,560);}

/* ---------- talent ---------- */
function tfiltered(){const f=S.tf,q=(f.q||"").toLowerCase();return STUDENTS.filter(s=>(!f.areas.size||s.areas.some(a=>f.areas.has(a)))&&[...f.langs].every(l=>s.langs.includes(l))&&s.rate>=f.rate&&s.price[0]<=f.maxPrice&&(!q||(s.n+" "+s.prog+" "+s.skills.join(" ")+" "+s.uni).toLowerCase().includes(q))).sort((a,b)=>b.rate-a.rate);}
function talentCard(s){const sl=S.shortlist.has(s.id);return `<article class="tcard" onclick="stuDrawer('${s.id}')"><div class="row">${av(s,46)}<div class="grow"><div class="between"><b class="ell">${esc(s.n)}</b><button class="save ${sl?"on":""}" aria-label="${sl?"Remove from shortlist":"Add to shortlist"}" onclick="event.stopPropagation();toggleSL('${s.id}')">${ic("star",19,2,sl?"currentColor":"none")}</button></div><div class="xs muted ell">${s.prog} · ${s.uni}</div></div></div>
  <div class="s" style="line-height:1.35">${esc(s.head)}</div><div class="row" style="flex-wrap:wrap;gap:5px">${s.langs.map(langS).join("")}${s.skills.slice(0,2).map(k=>`<span class="chip">${k}</span>`).join("")}</div>
  <div class="between" style="margin-top:auto;padding-top:8px;border-top:1px solid var(--line2)"><span class="xs">${s.rate?`<span class="stars">★</span> <b>${s.rate.toFixed(1)}</b> · ${s.done} projects`:'<span class="pill p-warn">New</span>'}</span><b class="xs num">${kfmt(s.price[0])} to ${kfmt(s.price[1])}</b></div></article>`;}
CV.talent=()=>{const f=S.tf,l=tfiltered();const ck=(set,v,lab)=>`<div class="ck ${set.has(v)?"on":""}" onclick="S.tf.${set===f.areas?"areas":"langs"}.has('${v}')?S.tf.${set===f.areas?"areas":"langs"}.delete('${v}'):S.tf.${set===f.areas?"areas":"langs"}.add('${v}');coRender()"><span class="box">${ic("check",12,3)}</span>${lab}</div>`;
 return `<div class="wh"><div><h1>Find talent</h1><p>Search verified students and invite them to your projects.</p></div></div>
  <div class="row" style="align-items:flex-start;gap:16px"><aside class="filters"><h4>Area</h4>${Object.keys(AREAS).map(a=>ck(f.areas,a,a)).join("")}
   <h4>Speaks</h4>${["FR","EN","ES"].map(x=>ck(f.langs,x,LANGN[x])).join("")}
   <h4>Minimum rating</h4><div class="opts">${[[0,"Any"],[4.5,"4.5+"],[4.8,"4.8+"]].map(([v,t])=>`<button class="opt ${f.rate===v?"on":""}" onclick="S.tf.rate=${v};coRender()">${t}</button>`).join("")}</div>
   <h4>Starts at up to <b id="mpx" style="color:var(--ink)">${kfmt(f.maxPrice)}</b></h4><input type="range" min="150000" max="600000" step="25000" value="${f.maxPrice}" aria-label="Maximum starting price" oninput="$('#mpx').textContent=kfmt(+this.value)" onchange="S.tf.maxPrice=+this.value;coRender()">
   <button class="btn sec sm mt10" style="width:100%" onclick="S.tf={areas:new Set(),langs:new Set(),rate:0,maxPrice:600000,q:''};coRender()">Reset filters</button></aside>
   <div class="grow"><div class="row" style="margin-bottom:12px"><div class="search grow">${ic("search",18)}<input placeholder="Skill, university, name" value="${esc(f.q||"")}" aria-label="Search students" onkeydown="if(event.key==='Enter'){S.tf.q=this.value;coRender()}"></div><span class="s muted" style="white-space:nowrap"><b style="color:var(--ink)">${l.length}</b> students</span></div>
   ${l.length?`<div class="tgrid">${l.map(talentCard).join("")}</div>`:`<div class="wcard" style="padding:30px;text-align:center"><b>No student matches</b><p class="s muted">Remove a filter to see more profiles.</p></div>`}</div></div>`;};
function toggleSL(id){S.shortlist.has(id)?S.shortlist.delete(id):S.shortlist.add(id);if(S.coRoute[0]==="talent")coRender();else renderTray();}
function renderTray(){const t=$("#tray");if(!t)return;const l=[...S.shortlist].map(ST);t.classList.toggle("on",S.mode==="co"&&S.coRoute[0]==="talent"&&l.length>0);
 t.innerHTML=`<span class="row" style="gap:-6px">${l.map(s=>av(s,30)).join("")}</span><span class="s"><b>${l.length}</b> in shortlist</span><button class="btn sm" ${l.length<2?"disabled":""} onclick="compareModal()">Compare</button><button class="ib flat" style="color:#fff" aria-label="Clear shortlist" onclick="S.shortlist.clear();coRender()">${ic("close",18)}</button>`;}
function compareModal(){const l=[...S.shortlist].map(ST).slice(0,3);const best=(f,mx)=>{const v=l.map(f);const b=mx?Math.max(...v):Math.min(...v);return v.map(x=>x===b);};
 const rows=[["Rating",s=>s.rate||0,s=>s.rate?s.rate.toFixed(1)+" ★":"New",true],["Projects done",s=>s.done,s=>s.done,true],["Starting price",s=>s.price[0],s=>fmt(s.price[0]),false],["Answers in",s=>parseInt(s.resp),s=>s.resp,false]];
 coModal(`${mh("Compare shortlist")}<div class="mb scrollx"><table class="cmp"><thead><tr><th></th>${l.map(s=>`<td><div class="row">${av(s,36)}<div><b class="s">${esc(s.n)}</b><div class="xs muted">${s.uni}</div></div></div></td>`).join("")}</tr></thead><tbody>
  ${rows.map(([t,f,d,mx])=>{const b=best(f,mx);return `<tr><th>${t}</th>${l.map((s,i)=>`<td><span class="${b[i]?"pill p-ok":""}" style="${b[i]?"":"padding:3px 0"}">${d(s)}${b[i]?" · best":""}</span></td>`).join("")}</tr>`;}).join("")}
  <tr><th>Languages</th>${l.map(s=>`<td><span class="row" style="gap:4px;flex-wrap:wrap">${s.langs.map(langS).join("")}</span></td>`).join("")}</tr>
  <tr><th>Skills</th>${l.map(s=>`<td class="s">${s.skills.slice(0,3).join(", ")}</td>`).join("")}</tr>
  <tr><th>Available</th>${l.map(s=>`<td class="s">${s.avail}</td>`).join("")}</tr>
  <tr><th></th>${l.map(s=>`<td><button class="btn sm" onclick="inviteModal('${s.id}')">Invite</button></td>`).join("")}</tr></tbody></table><p class="xs muted">"Best" is marked in green and with the word best.</p></div>`,820);}
function stuDrawer(sid){const s=ST(sid),sl=S.shortlist.has(sid);
 coDrawer(`<div class="dh"><b>Student profile</b><button class="ib flat" aria-label="Close" onclick="coClose()">${ic("close",20)}</button></div><div class="db">
  <div style="height:70px;border-radius:14px;background:linear-gradient(120deg,${s.c1},${s.c2})"></div><div style="margin:-30px 0 0 14px">${av(s,64).replace('class="av"','class="av" style="border:4px solid var(--card)"')}</div>
  <h3 style="margin:8px 0 2px;font-size:1.2rem">${esc(s.n)}</h3><div class="s">${esc(s.head)}</div><div class="xs muted">${s.prog} · ${s.sem} · ${s.uni} · ${s.town}</div>
  <div class="stats3 mt14"><div><b>${s.rate?s.rate.toFixed(1):"New"}</b><small>Rating</small></div><div><b>${s.done}</b><small>Projects</small></div><div><b>${s.resp}</b><small>Answers in</small></div></div>
  <div class="lbl mt20">About</div><p class="s" style="margin:0;line-height:1.55">${esc(s.note)}</p>
  <div class="lbl mt14">Languages</div><div class="row" style="flex-wrap:wrap;gap:6px">${s.langs.map(lang).join("")}</div>
  <div class="lbl mt14">Skills</div><div class="row" style="flex-wrap:wrap;gap:6px">${s.skills.map(k=>`<span class="chip">${k}</span>`).join("")}</div>
  ${sid==="s1"?`<div class="lbl mt14">Experience</div><div class="s" style="line-height:1.7">Founder, Français avec Guillaume (online French school)<br>Teacher, French and A-Level Business, St. Matthew School<br>2 years living and working in New Zealand</div>
   <div class="lbl mt14">Certificates</div>${S.certs.map(c=>`<div class="between s" style="padding:5px 0"><span>${esc(c.title)}</span><span class="pill p-ok">${c.rate.toFixed(1)} ★</span></div>`).join("")}`:""}
  <div class="lines mt14"><div><span class="muted">Usual price</span><b class="num">${fmt(s.price[0])} to ${fmt(s.price[1])}</b></div><div><span class="muted">Availability</span><b>${s.avail}</b></div></div></div>
  <div class="df"><button class="btn sec sm" onclick="toggleSL('${sid}');stuDrawer('${sid}')">${sl?"★ Shortlisted":"☆ Shortlist"}</button><button class="btn sm grow" onclick="inviteModal('${sid}')">Invite to a project</button></div>`);}
function inviteModal(sid){const s=ST(sid),open=coProjects().filter(p=>p.status==="open"||p.status==="draft");S.invP=S.invP||(open[0]&&open[0].id);$("#drawer").classList.remove("on");
 coModal(`${mh("Invite "+esc(s.n.split(" ")[0]))}<div class="mb">${open.length?open.map(p=>`<div class="radio ${S.invP===p.id?"on":""}" onclick="S.invP='${p.id}';inviteModal('${sid}')"><span class="rd"></span><div class="grow"><b class="s">${esc(p.title)}</b><div class="xs muted">${fmt(p.pay)} · ${p.status==="draft"?"draft, will be published":"open"}</div></div></div>`).join(""):'<p>Post a project first.</p>'}
  <div class="field mt10"><label for="imsg">Message</label><textarea id="imsg" class="inp" rows="3">Hi ${esc(s.n.split(" ")[0])}, we liked your profile. Would you be interested in this project?</textarea></div></div>
  <div class="mf"><button class="btn sec" onclick="coClose()">Cancel</button><button class="btn" onclick="sendInvite('${sid}')">${ic("send",16)} Send invitation</button></div>`,560);}
function sendInvite(sid){const p=P(S.invP);if(p&&p.status==="draft"){p.status="open";p.posted="Nov 23";S.coApps[p.id]=S.coApps[p.id]||[];}
 if(sid==="s1"&&p){S.notifs.unshift({t:`Exportadora Andina invited you to "${p.title}"`,w:"now",go:["project",p.id],u:1});banner("New invitation",`Exportadora Andina invited you to "${p.title}"`,["project",p.id]);}
 coClose();wtoast(`Invitation sent to ${ST(sid).n.split(" ")[0]}`,"send");coRender();}

/* ---------- messages ---------- */
CV.messages=()=>{const ts=Object.entries(S.threads).filter(([k,t])=>t.co==="andina");if(!S.threads[S.coThread])S.coThread=ts[0][0];const th=S.threads[S.coThread],s=ST(th.stu);
 return `<div class="wh"><div><h1>Messages</h1><p>Conversations with your students</p></div></div><div class="inbox" style="height:calc(100% - 70px);min-height:480px">
  <div class="lst">${ts.map(([k,t])=>{const l=t.msgs.at(-1),st=ST(t.stu);return `<div class="it ${k===S.coThread?"on":""}" onclick="S.coThread='${k}';coRender()">${av(st,40)}<div class="grow"><div class="between"><b class="s ell">${esc(st.n)}</b><span class="xs muted">${l?l[2]:""}</span></div><div class="xs muted">${esc(t.ctx)}</div><div class="xs ell mt6 ${l&&l[0]==="stu"?"b":"muted"}">${l?(l[0]==="co"?"You: ":"")+(typeof l[1]==="string"?esc(l[1]):"Sent a file"):"New conversation"}</div></div></div>`;}).join("")}</div>
  <div class="conv"><div class="row" style="padding:12px 16px;border-bottom:1px solid var(--line);background:var(--card)">${av(s,38)}<div class="grow"><b class="s">${esc(s.n)}</b><div class="xs muted">${esc(th.ctx)} · answers in ${s.resp}</div></div><button class="btn sm sec" onclick="stuDrawer('${s.id}')">Profile</button></div>
   <div class="msgs" id="cmsgs">${msgsHTML(th,"co")}</div>
   <div class="composer"><div class="in"><input id="ccin" placeholder="Write to ${esc(s.n.split(" ")[0])}" aria-label="Message" onkeydown="if(event.key==='Enter')sendCo()"><button class="sendb" aria-label="Send" onclick="sendCo()">${ic("send",18)}</button></div></div></div></div>`;};
CVA.messages=()=>{const m=$("#cmsgs");m.scrollTop=m.scrollHeight;};
function sendCo(){const i=$("#ccin"),v=i.value.trim();if(!v)return;const k=S.coThread,th=S.threads[k];th.msgs.push(["co",v,nowT()]);i.value="";
 if(th.stu==="s1"){S.readStu.delete(k);S.notifs.unshift({t:`Laura sent a message: "${v.slice(0,50)}"`,w:"now",go:["chat",k],u:1});}
 coRender();const m=$("#cmsgs");m.insertAdjacentHTML("beforeend",`<div class="typing" id="ctyp"><i></i><i></i><i></i></div>`);m.scrollTop=m.scrollHeight;
 setTimeout(()=>{th.msgs.push(["stu",["Perfect, thank you!","D'accord, I'll prepare it.","Sure, I can do that this week."][th.msgs.length%3],nowT()]);if(S.mode==="co"&&S.coRoute[0]==="messages"&&S.coThread===k)coRender();},1600);}

/* ---------- payments ---------- */
CV.payments=()=>{const paid=S.invoices.filter(x=>x.st==="Paid").reduce((a,x)=>a+x.a,0);
 return `<div class="wh"><div><h1>Payments</h1><p>Escrow, invoices and SkillBridge fees</p></div><button class="btn sec sm" onclick="exportCSV()">${ic("copy",16)} Copy as CSV</button></div>
  <div class="kpis"><div class="kpi"><small>${ic("lock",15)}Held in escrow</small><b class="num">${kfmt(coEscrow())}</b><span class="dl muted">Across ${Object.entries(S.work).filter(([k])=>P(k).co==="andina"&&P(k).status==="active").length} projects</span></div>
   <div class="kpi"><small>${ic("check",15)}Paid to students</small><b class="num">${kfmt(paid)}</b><span class="dl muted">In 2026</span></div>
   <div class="kpi"><small>${ic("card",15)}SkillBridge fees</small><b class="num">${kfmt(paid*FEE)}</b><span class="dl muted">12% + IVA on the fee</span></div>
   <div class="kpi"><small>${ic("doc",15)}Invoices</small><b>${S.invoices.length}</b><span class="dl muted">Electronic invoice (DIAN)</span></div></div>
  <div class="g2"><section class="wcard"><div class="hd"><h3>Invoices</h3></div><div class="bdy scrollx"><table class="tbl"><thead><tr><th>Number</th><th>Project</th><th>Student</th><th>Date</th><th class="r">Student pay</th><th class="r">Fee + IVA</th><th>Status</th></tr></thead><tbody>
   ${S.invoices.map(x=>{const p=P(x.p),w=S.work[x.p];return `<tr><td class="s b">${x.n}</td><td class="s">${esc(p.title)}</td><td class="s">${w?esc(ST(w.stu).n):""}</td><td class="xs muted">${x.d}</td><td class="r num">${fmt(x.a)}</td><td class="r num muted">${fmt(x.a*FEE*(1+IVA))}</td><td><span class="pill ${x.st==="Paid"?"p-ok":"p-brand"}">${x.st==="Paid"?"Released":"In escrow"}</span></td></tr>`;}).join("")}</tbody></table></div></section>
   <section class="wcard"><div class="hd"><h3>How the money moves</h3></div><div class="bdy"><ol style="margin:0;padding-left:18px;line-height:1.7" class="s"><li>You hire a student and pay the full amount into escrow.</li><li>The student delivers each milestone.</li><li>You approve, the student gets that part within 48 h.</li><li>No answer in 5 days: the part is released automatically.</li></ol>
    <div class="card mt14" style="box-shadow:none;background:var(--brand-soft);border-color:transparent"><div class="s" style="color:var(--brand-ink)"><b>The student gets 100% of the agreed pay.</b> SkillBridge earns a 12% fee paid by the company, plus IVA on that fee.</div></div></div></section></div>`;};
function exportCSV(){const rows=[["number","project","date","student_pay","fee_with_iva","status"],...S.invoices.map(x=>[x.n,P(x.p).title,x.d,x.a,Math.round(x.a*FEE*(1+IVA)),x.st])];const csv=rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(",")).join("\n");
 try{navigator.clipboard.writeText(csv).then(()=>wtoast("CSV copied, paste it in Excel","copy"),()=>wtoast("Copy not allowed here","info"));}catch(e){wtoast("Copy not allowed here","info");}}

/* ---------- post a project ---------- */
function openPost(id){const d=id?P(id):null;S.draft={id:id||null,step:1,title:d?d.title:"Product catalogue in English for US buyers",area:d?d.area:"Languages",desc:d?d.desc:"Translate our 20-page catalogue of coffee and flowers into English for buyers in the US. Product names stay in Spanish.",
  deliv:d?d.deliv.slice():["20 pages translated in our template","Glossary of product names"],skills:new Set(d?d.skills:["Translation","English C1"]),langs:new Set(d?d.langs:["EN","ES"]),mode:d?d.mode:"Remote",dur:d?d.dur:"2 weeks",budget:d?d.pay:320000};renderPost();}
function renderPost(){const d=S.draft,st=d.step,names=["Basics","Deliverables","Talent","Budget"];
 const lo=Math.round(d.budget>0?240000:0),hi=380000;const dist=[2,4,7,11,14,12,9,6,4,2];const bucket=Math.max(0,Math.min(9,Math.floor((d.budget-150000)/45000)));
 const mc=STUDENTS.filter(s=>[...d.langs].every(l=>s.langs.includes(l))).length*6+4;
 let f="";
 if(st===1)f=`<div class="field"><label for="pt">Project title</label><input id="pt" class="inp" value="${esc(d.title)}" oninput="S.draft.title=this.value;$('#pvt').textContent=this.value||'Untitled project'"></div>
  <div class="field"><label>Area</label><div class="opts">${Object.keys(AREAS).map(a=>`<button class="opt ${d.area===a?"on":""}" onclick="S.draft.area='${a}';renderPost()">${ic(AREAS[a].ic,15)}${a}</button>`).join("")}</div></div>
  <div class="field"><label for="pd">What do you need?</label><textarea id="pd" class="inp" rows="5" oninput="S.draft.desc=this.value">${esc(d.desc)}</textarea><div class="xs muted mt6">Tip: say who the result is for and what "done" looks like.</div></div>`;
 if(st===2)f=`<p class="s muted" style="margin:0 0 12px">List what the student hands in. Each deliverable becomes a milestone, paid separately.</p>
  ${d.deliv.map((x,i)=>`<div class="ms" style="align-items:center"><span class="ix">${i+1}</span><span class="s grow">${esc(x)}</span><button class="ib flat" aria-label="Remove" onclick="S.draft.deliv.splice(${i},1);renderPost()">${ic("close",16)}</button></div>`).join("")}
  <div class="row mt10"><input id="nd" class="inp" placeholder="Add a deliverable" onkeydown="if(event.key==='Enter')addD()"><button class="btn sm" onclick="addD()">Add</button></div>
  <div class="card mt14" style="box-shadow:none;background:var(--brand-soft);border-color:transparent"><div class="s" style="color:var(--brand-ink)">${ic("spark",15)} Suggested for ${d.area}: <b>"One round of corrections included"</b> <button class="link" onclick="S.draft.deliv.push('One round of corrections included');renderPost()">Add</button></div></div>`;
 if(st===3)f=`<div class="field"><label>Skills</label><div class="opts">${["Translation","English C1","French","Proofreading","Excel","Market research","Canva","Power BI"].map(s=>`<button class="opt ${d.skills.has(s)?"on":""}" onclick="S.draft.skills.has('${s}')?S.draft.skills.delete('${s}'):S.draft.skills.add('${s}');renderPost()">${s}</button>`).join("")}</div></div>
  <div class="field"><label>Languages required</label><div class="opts">${["ES","EN","FR"].map(l=>`<button class="opt ${d.langs.has(l)?"on":""}" onclick="S.draft.langs.has('${l}')?S.draft.langs.delete('${l}'):S.draft.langs.add('${l}');renderPost()">${LANGN[l]}</button>`).join("")}</div></div>
  <div class="field"><label>Where</label><div class="opts">${["Remote","Hybrid","On-site"].map(m=>`<button class="opt ${d.mode===m?"on":""}" onclick="S.draft.mode='${m}';renderPost()">${m}</button>`).join("")}</div></div>
  <div class="card" style="box-shadow:none"><div class="between"><span class="s"><b>${mc} verified students</b> match right now</span>${ring(Math.min(100,mc*2),44,5)}</div></div>`;
 if(st===4)f=`<div class="field"><label>Duration</label><div class="opts">${["1 week","2 weeks","3 weeks","1 month"].map(x=>`<button class="opt ${d.dur===x?"on":""}" onclick="S.draft.dur='${x}';renderPost()">${x}</button>`).join("")}</div></div>
  <div class="field"><div class="between"><label for="bd" style="margin:0">Budget for the student</label><b class="num" id="bdv">${fmt(d.budget)}</b></div><input id="bd" type="range" min="150000" max="600000" step="10000" value="${d.budget}" aria-label="Budget" oninput="S.draft.budget=+this.value;$('#bdv').textContent=fmt(+this.value)" onchange="renderPost()">
   <div class="lbl mt10">What companies paid for similar ${d.area.toLowerCase()} projects</div><div class="dist">${dist.map((h,i)=>`<i class="${i===bucket?"me":i>=2&&i<=5?"in":""}" style="height:${h*5}px" title="${kfmt(150000+i*45000)}"></i>`).join("")}</div>
   <div class="between xs muted mt6"><span>$150k</span><span>$600k</span></div>
   <div class="xs mt10 row" style="gap:12px"><span class="row" style="gap:5px"><i style="width:10px;height:10px;border-radius:2px;background:var(--brand)"></i>Most common</span><span class="row" style="gap:5px"><i style="width:10px;height:10px;border-radius:2px;background:var(--coral)"></i>Your budget</span></div>
   <div class="card mt10" style="box-shadow:none;background:${d.budget<240000?"var(--warn-soft)":d.budget>380000?"var(--chip)":"var(--ok-soft)"};border-color:transparent"><b class="s" style="color:${d.budget<240000?"var(--warn)":d.budget>380000?"var(--ink)":"var(--ok)"}">${d.budget<240000?"Low budget: fewer students will apply.":d.budget>380000?"High budget: you will get many applicants.":"Good budget: in the usual range."}</b></div></div>
  <div class="lines"><div><span>Student payment</span><b class="num">${fmt(d.budget)}</b></div><div><span class="muted">SkillBridge fee (12%) + IVA</span><span class="num muted">${fmt(d.budget*FEE*(1+IVA))}</span></div><div class="tot"><span>You pay when you hire</span><span class="num">${fmt(d.budget*(1+FEE*(1+IVA)))}</span></div></div>`;
 const pv=`<div class="preview"><div class="xs muted b" style="margin-bottom:8px">Preview · what students see</div><article class="mcard" style="flex:none;width:100%;cursor:default"><div class="cv">${cover(d.area,110,3)}<span class="mt">${Math.min(99,70+mc)}% match</span>${logo("andina",42)}</div><div class="bd"><div class="ti" id="pvt">${esc(d.title)||"Untitled project"}</div><div class="xs muted mt6">Exportadora Andina · ${d.mode}</div><div class="between mt10"><span class="money">${fmt(d.budget)}</span><span class="chip">${ic("clock",13)}${d.dur}</span></div></div></article>
  <div class="lbl mt14">Milestones</div>${d.deliv.map((x,i)=>`<div class="between xs" style="padding:4px 0"><span class="ell">${i+1}. ${esc(x)}</span><b class="num">${kfmt(d.budget*(d.deliv.length===3?[.3,.4,.3][i]:d.deliv.length===2?.5:1/d.deliv.length))}</b></div>`).join("")}</div>`;
 coModal(`${mh(d.id?"Edit draft":"New project")}<div class="mb"><div class="stepper" style="padding:0">${names.map((n,i)=>`<i class="${i<st?"on":""}"></i>`).join("")}</div>
  <div class="xs muted b" style="margin:-8px 0 12px">Step ${st} of 4 · ${names[st-1]}</div><div class="wiz2"><div>${f}</div>${pv}</div></div>
  <div class="mf"><button class="btn sec" onclick="saveDraft()" style="margin-right:auto">Save draft</button>${st>1?`<button class="btn sec" onclick="S.draft.step--;renderPost()">Back</button>`:""}<button class="btn" onclick="${st<4?"S.draft.step++;renderPost()":"publishP()"}">${st<4?"Continue":ic("send",16)+" Publish project"}</button></div>`,980);}
function addD(){const v=$("#nd").value.trim();if(v){S.draft.deliv.push(v);renderPost();}}
function draftToP(st){const d=S.draft;const o={co:"andina",area:d.area,title:d.title||"Untitled project",pay:d.budget,dur:d.dur,hours:{"1 week":8,"2 weeks":16,"3 weeks":24,"1 month":32}[d.dur],mode:d.mode,town:"Bogotá",closes:7,applicants:0,status:st,posted:"Nov 23",desc:d.desc,deliv:d.deliv.length?d.deliv:["Final delivery"],skills:[...d.skills],langs:[...d.langs]};
 if(d.id){Object.assign(P(d.id),o);return P(d.id);}o.id="n"+(PROJECTS.length+1);o.match=[...d.langs].every(l=>["FR","ES","EN"].includes(l))?92:70;o.why=[["y","Your languages match"],["y","Area matches your skills"]];PROJECTS.unshift(o);return o;}
function saveDraft(){draftToP("draft");coClose();wtoast("Draft saved");coGo("board");}
function publishP(){const p=draftToP("open");S.coApps[p.id]=S.coApps[p.id]||[];S.notifs.unshift({t:`New match: ${p.title} (Exportadora Andina)`,w:"now",go:["project",p.id],u:1});
 coClose();S.ptab2="apps";coGo("proj",p.id);wtoast("Project published. Matching students were notified","send");}
